#!/usr/bin/env node
// Art-Net DMX controller — zero dependencies. Data-driven with a live in-app
// fixture editor. Fixtures/profiles persist to patch.json + profiles.json
// (auto-created next to this file on first run). Add/edit fixtures from the
// browser — no restart, no code edits.
//
// Run:  node artnet-controller.js   then open the printed URL on your iPhone.

const http  = require('http');
const https = require('https');
const dgram = require('dgram');
const os    = require('os');
const fs    = require('fs');
const path  = require('path');
const { execSync } = require('child_process');

// BUILD: bump on every edit (YYYY-MM-DD + letter). Shown in the Settings footer and console,
// so any Claude thread (either account) can confirm it's working from the same version.
const BUILD = '2026-10-19a';
// 08y SMOKE MODE (DMX_SMOKE=1): the update gate starts a candidate build in a temp folder on a spare port and checks that it
// answers /health, /cc and /sim before anything is swapped. In this mode nothing leaves the machine: UDP sends are dropped and
// binds go to a random local port, outbound TCP (Kasa, Pi bridge, HTTP to other hosts) is refused, no HTTPS, no backups.
const SMOKE = process.env.DMX_SMOKE==='1';
const REAL_SPAWN = require('child_process').spawn;   // 16f+: kept before SMOKE stubs it -- used ONLY for IMPORT A MIX's listener browser, and in SMOKE only when DMX_HEADLESS names one (tests)
// 12s/12u DESK MODE (Mike 10-13: the Controller at work, no Rig; 'the work system and home system can never collide'). The FOLDER is
// the identity: DESK.cmd's first run leaves DESK-FOLDER.txt and from then on that folder is always DESK, however it's started.
// C:\DMX (home) is never DESK: there the env + the marker are ignored (and DESK.cmd refuses to run there).
// In DESK nothing leaves the machine: no Art-Net, no UDP / TCP to any other host (no Kasa / Govee / Pi / node probing on the work
// network); the CC, the SiM MIRROR and the Desk Pi are served locally as usual.
const DESK_MARK = path.join(__dirname, 'DESK-FOLDER.txt'), HOME_DIR = /^[a-z]:[\\\/]dmx[\\\/]?$/i.test(__dirname);
const DESKMODE = !SMOKE && !HOME_DIR && (process.env.DMX_DESK==='1' || fs.existsSync(DESK_MARK));
if(HOME_DIR && (process.env.DMX_DESK==='1' || fs.existsSync(DESK_MARK))) console.log('NOTE: this is the HOME folder (C:\\DMX) -- DESK mode is ignored here.');
if(DESKMODE){ try{ if(!fs.existsSync(DESK_MARK)) fs.writeFileSync(DESK_MARK, 'This folder runs the DMX Controller in DESK MODE (no Rig, nothing goes out on the network).\r\nDelete this file only if you really want this copy to drive a Rig.\r\n'); }catch(e){}
  const net0=require('net'), dP=dgram.Socket.prototype, nP=net0.Socket.prototype, _send=dP.send, _conn=nP.connect, local=h=>/^(127\.|localhost$|::1$|::ffff:127\.)/.test(String(h||''));
  dP.send=function(){ const a=[].slice.call(arguments), host=a.find(function(x,i){ return i>0 && typeof x==='string'; }); if(local(host)) return _send.apply(this,a); const cb=a.slice().reverse().find(function(x){ return typeof x==='function'; }); if(cb) process.nextTick(cb,null,0); };
  nP.connect=function(){ const a=arguments[0], host=(a&&typeof a==='object')?(a.host||'localhost'):(typeof arguments[1]==='string'?arguments[1]:'localhost');
    if(!local(host)){ const me=this; process.nextTick(function(){ const e=new Error('DESK mode: no network ('+host+')'); e.code='ECONNREFUSED'; me.destroy(e); }); return this; } return _conn.apply(this,arguments); }; }
const HTTP_PORT   = SMOKE ? (+process.env.DMX_SMOKE_PORT||18080) : 8080;
if(SMOKE){ const net0=require('net'), dP=dgram.Socket.prototype, nP=net0.Socket.prototype, _bind=dP.bind, _conn=nP.connect;
  dP.send=function(){ const cb=[].slice.call(arguments).reverse().find(function(a){ return typeof a==='function'; }); if(cb) process.nextTick(cb,null,0); };
  dP.bind=function(){ const cb=[].slice.call(arguments).find(function(a){ return typeof a==='function'; }); return _bind.call(this,{port:0,address:'127.0.0.1'},cb); };
  ['setBroadcast','setMulticastTTL','setMulticastLoopback','addMembership','dropMembership','setTTL'].forEach(function(k){ dP[k]=function(){}; });
  nP.connect=function(){ const a=arguments[0], host=(a&&typeof a==='object')?(a.host||'localhost'):(typeof arguments[1]==='string'?arguments[1]:'localhost');
    if(!/^(127\.|localhost$|::1$)/.test(String(host))){ const me=this; process.nextTick(function(){ const e=new Error('smoke test: no network ('+host+')'); e.code='ECONNREFUSED'; me.destroy(e); }); return this; }
    return _conn.apply(this,arguments); };
  // no child processes either: a test copy must never start djay OCR, UxPlay, desktop clearing, ping or a watchdog next to the live one
  const cpm=require('child_process'), EE=require('events'), PT=require('stream').PassThrough, noCp=function(){ const e=new Error('smoke test: no child processes'); e.code='ENOENT'; return e; };
  const fake=function(){ const c=new EE(); c.stdout=new PT(); c.stderr=new PT(); c.stdin=new PT(); c.pid=0; c.kill=function(){ return true; }; c.unref=function(){}; c.ref=function(){};
    process.nextTick(function(){ if(c.listenerCount('error')) c.emit('error',noCp()); c.stdout.end(); c.stderr.end(); c.emit('exit',1,null); c.emit('close',1,null); }); return c; };
  cpm.spawn=function(){ return fake(); }; cpm.execFile=cpm.exec=function(){ const cb=[].slice.call(arguments).find(function(x){ return typeof x==='function'; }); if(cb) process.nextTick(cb,noCp(),'',''); return fake(); }; }
// 08b CONSOLE-FREEZE GUARD (Mike, 10-08): in the classic Windows console a click starts a text selection ('Select' in the
// title) and the next console write BLOCKS the whole controller until Esc -- 66 s freezes, phones dead, port 8080 held
// by a zombie. All output now goes to controller.log (async); the window shows one line. Rotates at 5 MB.
(function(){ if(!((process.platform==='win32' && process.stdout.isTTY) || process.env.DMX_LOGFILE)) return;
  try{ const lf=path.join(__dirname,'controller.log'); try{ if(fs.statSync(lf).size>5e6) fs.renameSync(lf, path.join(__dirname,'controller.old.log')); }catch(e){}
    const ws=fs.createWriteStream(lf,{flags:'a'}); ws.on('error',function(){});
    try{ fs.writeSync(1, 'Art-Net DMX Controller '+BUILD+' running -- output goes to controller.log (clicking this window is safe)\n'); }catch(e){}
    ws.write('\n==== '+new Date().toISOString()+'  start '+BUILD+' ====\n');
    const w=function(c, enc, cb){ try{ ws.write(c, typeof enc==='string'?enc:undefined); }catch(e){} if(typeof enc==='function') enc(); else if(typeof cb==='function') cb(); return true; };
    process.stdout.write=w; process.stderr.write=w;
    process.on('uncaughtException', function(e){ try{ fs.appendFileSync(lf, 'UNCAUGHT '+(e&&e.stack||e)+'\n'); }catch(x){} try{ fs.writeSync(2, 'Controller crashed: '+(e&&e.message)+' (details in controller.log)\n'); }catch(x){} process.exit(1); });
  }catch(e){} })();
const STARTED_AT = new Date();   // doubles as a build indicator -- a restart is required to load any code change, so this timestamp always reflects "what's actually running," not just what file's on disk
const HTTPS_PORT  = 8443;   // used only if cert.pem + key.pem are present (needed for mic access — Safari requires a secure context)
const ARTNET_PORT = 6454;
const CERT_FILE = path.join(__dirname, 'cert.pem');
const KEY_FILE  = path.join(__dirname, 'key.pem');
const PATCH_FILE   = path.join(__dirname, 'patch.json');
const PROFILE_FILE = path.join(__dirname, 'profiles.json');
const SETTINGS_FILE = path.join(__dirname, 'settings.json');
const SCENES_FILE   = path.join(__dirname, 'scenes.json');
const BRIDGE_FILE   = path.join(__dirname, 'bridge.json');
const LINK_FILE     = path.join(__dirname, 'linkfire.json');
const LIVESHOW_FILE = path.join(__dirname, 'liveshow.json');
const PERF_PAGES_FILE = path.join(__dirname, 'perform-pages.json');   // Performance paging: {sceneId: 1..4}; unassigned = page 1
let perfPagesRaw=null; try{ perfPagesRaw=JSON.parse(fs.readFileSync(PERF_PAGES_FILE,'utf8')); }catch(e){}
let perfPages=null;   // {sceneId:[pages 1..4]}; a scene with no entry is on no page. Built lazily (needs scenes loaded).
function savePerfPages(){ try{ fs.writeFileSync(PERF_PAGES_FILE, JSON.stringify({v:2, pages:perfPages},null,2)); }catch(e){} }
function getPerfPages(){
  if(perfPages) return perfPages;
  const out={}, count=[0,0,0,0,0];
  function add(id,pg){ if(pg>=1 && pg<=4 && count[pg]<8 && !(out[id]||[]).includes(pg)){ (out[id]=out[id]||[]).push(pg); count[pg]++; } }
  if(perfPagesRaw && perfPagesRaw.v===2) scenes.forEach(sc=>(perfPagesRaw.pages[sc.id]||[]).forEach(pg=>add(sc.id,pg|0)));
  else { const old=perfPagesRaw||{}; scenes.forEach(sc=>add(sc.id, old[sc.id]?(old[sc.id]|0):1)); }   // pre-v2 file (or none): unassigned meant page 1, capped at 8 = what was visible
  perfPages=out; savePerfPages(); return perfPages;
}

// --- seed defaults on first run ---------------------------------------------
const SEED_PROFILES = {
  "line-anim-34": ["Total Switch","Out of Bounds Mode & Pattern Size","Animation & Line Gallery Selection","Animation Pattern & Line Effect Selection","Pattern Scaling","Pattern Rotation","Horizontal Movement","Vertical Movement","Horizontal Zoom","Vertical Zoom","Force Tinting","Color Change","Node Highlighting","Node Expansion","Gradient","Degree of Distortion","Filter Selection","2nd Pattern Switch","Out of Bounds Mode & Pattern Size","No Function","2nd Pattern Selection","Pattern Scaling","Pattern Rotation","Horizontal Movement","Vertical Movement","Horizontal Zoom","Vertical Zoom","Force Tinting","Color Change","Node Highlighting","Node Expansion","Gradient","Degree of Distortion","Filter Selection"]
};
const SEED_PATCH = [ { name:"Fixture 1", profile:"line-anim-34", universe:0, start:1 } ];

function load(file, seed){
  try { return JSON.parse(fs.readFileSync(file,'utf8')); }
  catch(e){ fs.writeFileSync(file, JSON.stringify(seed,null,2)); return JSON.parse(JSON.stringify(seed)); }
}
let profiles = load(PROFILE_FILE, SEED_PROFILES);
let patch    = load(PATCH_FILE,   SEED_PATCH);
function save(){ fs.writeFileSync(PATCH_FILE, JSON.stringify(patch,null,2)); fs.writeFileSync(PROFILE_FILE, JSON.stringify(profiles,null,2)); }

function getTailscaleHostname(){
  try{
    const out = execSync('tailscale status --json', { timeout: 2000, stdio: ['ignore','pipe','ignore'] }).toString();
    const self = JSON.parse(out).Self;
    return (self && self.DNSName) ? self.DNSName.replace(/\.$/, '') : null;   // trim the trailing dot Tailscale includes
  }catch(e){ return null; }
}

let state = load(SETTINGS_FILE, { targetIP: '192.168.1.255' });
if(!Array.isArray(state.kasa)) state.kasa = [];
function saveSettings(){ fs.writeFileSync(SETTINGS_FILE, JSON.stringify(state,null,2)); }

let scenes = load(SCENES_FILE, []);
function saveScenes(){ fs.writeFileSync(SCENES_FILE, JSON.stringify(scenes,null,2)); }

// --- Bridge: remote hit events from a device at the Amp (wired LAN, not WiFi) ----
// Same channel assignments as React mode's client-side strobe/laser -- keep these
// in sync if the fixtures ever get re-patched to different addresses.
const BRIDGE_STROBE_U=0, BRIDGE_STROBE_DIM_A=37, BRIDGE_STROBE_FLASH_A=41, BRIDGE_STROBE_RGB_A=[38,39,40];
// 27p: the strobe emits nothing while its colour channels (R,G,B = 38-40) are all 0 -- only the phone React page's
// "Initialize on Start" ever set them, so the Pi bridge / Link test / live show flashed dark until a colour was picked.
// Any strobe hit now sets white first IF the colour is still all-zero (a colour you chose is left alone).
function strobeColorWrites(){ const u=universes[BRIDGE_STROBE_U]; if(!u || BRIDGE_STROBE_RGB_A.some(function(a){ return u[a-1]>0; })) return []; return BRIDGE_STROBE_RGB_A.map(function(a){ return [BRIDGE_STROBE_U,a,255]; }); }
const BRIDGE_LASER_U=0, BRIDGE_LASER_CH1_A=1, LIVE_LASER_ON=60;   // 27s: Ch1 1-100 = on (above 100 breaks its motion channels)
let linkState = { bpm:0, beat:0, phase:0, playing:false, t:0 };   // latest Ableton Link reading from the Pi's link_bridge.py; not persisted, just live state
let bridge = load(BRIDGE_FILE, { minv:40, maxv:220, bright:255, decay:150, target:'both' });
// Three-band bridge (2026-09-24). Defaults tuned for house: kick 40-120Hz, clap 1-4kHz, hats 6-12kHz.
// Starting points only -- tune against real recordings. Pre-band files migrate with band 1 keeping
// the old single target, so existing behavior carries over.
// 27o: Kick band = 100-250 Hz @ 1.6 (the kick's punch; below ~100 Hz the sub / off-beat bass is as loud as the kick).
// Scored against the true kicks in each track's separated DRUM STEM (kicks found / hits on a kick):
//   Dare      40-120@1.5: 12%/14%   100-250@1.6: 95%/60%
//   Tell Me Why          85%/49%                  92%/69%
//   Deceiver             75%/64%                 100%/84%
// (27n's 120-300 @ 1.8 found only 50% on Tell Me Why.)
const BAND_ROLES=['beat \u00b7 strobe \u00b7 PAR pulse','build rolls','hi-hat groove','risers + crashes'];   // 06t: what each band actually does in the show (the old per-band 'target' does nothing)
const BRIDGE_BAND_DEFAULTS=[ {name:'Kick', lo:100, hi:250, sens:1.6, target:'both'},
                             {name:'Clap', lo:1000, hi:4000, sens:1.6, target:'off'},
                             {name:'Hats', lo:6000, hi:12000, sens:1.6, target:'off'},
                             {name:'Air', lo:12000, hi:16000, sens:1.3, target:'off'} ];   // Air: risers + phrase-start crashes (2026-09-25)
if(Array.isArray(bridge.bands) && bridge.bands[0] && !bridge.kick27o && ((bridge.bands[0].lo===40 && bridge.bands[0].hi===120) || (bridge.bands[0].lo===120 && bridge.bands[0].hi===300))){
  // 27o: move the old kick-band default (40-120, or 27n's 120-300) once; a sensitivity you'd tuned by hand is kept
  var s0=bridge.bands[0].sens; bridge.bands[0].lo=100; bridge.bands[0].hi=250; if(s0===undefined || s0===1.5 || s0===1.8) bridge.bands[0].sens=1.6;
  bridge.kick27o=true; try{ fs.writeFileSync(BRIDGE_FILE, JSON.stringify(bridge,null,2)); }catch(e){}
}
if(!Array.isArray(bridge.bands)){
  bridge.bands=BRIDGE_BAND_DEFAULTS.map(function(b,i){ return Object.assign({}, b, i===0 && bridge.target ? {target:bridge.target} : {}); });
  fs.writeFileSync(BRIDGE_FILE, JSON.stringify(bridge,null,2));
} else if(bridge.bands.length<BRIDGE_BAND_DEFAULTS.length){   // older file: keep the tuned bands, append the new ones
  for(let i=bridge.bands.length;i<BRIDGE_BAND_DEFAULTS.length;i++) bridge.bands.push(Object.assign({},BRIDGE_BAND_DEFAULTS[i]));
  fs.writeFileSync(BRIDGE_FILE, JSON.stringify(bridge,null,2));
}
let bridgeState={ levels:[0,0,0], active:[false,false,false], t:0 };   // live per-band activity from the bridge page (not persisted)
// Ableton Link beat-predictive firing. Unlike the audio bridge (react to a hit that already
// happened), this fires ON the predicted beat itself, using the live tempo/beat/phase that
// link_bridge.py posts to /linksync. leadMs fires early to cancel out DMX + fixture response
// lag; everyN fires every Nth beat instead of every beat (e.g. 4 = once per bar).
let linkFire = load(LINK_FILE, { enabled:false, target:'strobe', leadMs:0, everyN:1 }); linkFire.enabled=false;   // 06s: Link beat-fire retired (Audio Lab › Link is view only)
function saveLinkFire(){ fs.writeFileSync(LINK_FILE, JSON.stringify(linkFire,null,2)); }
let linkFireTimer=null, linkFireDecayTimer=null;
function linkStale(){ return !linkState.t || (Date.now()-linkState.t)>5000; }
function scheduleNextLinkBeat(){
  if(linkFireTimer){ clearTimeout(linkFireTimer); linkFireTimer=null; }
  if(!linkFire.enabled || linkStale() || !(linkState.bpm>0) || (typeof liveCfg!=='undefined' && liveCfg.enabled)) return;   // 26an: the live show owns the strobe
  const elapsedSec=(Date.now()-linkState.t)/1000;
  const beatNow=linkState.beat + elapsedSec*(linkState.bpm/60);
  const n=Math.max(1, linkFire.everyN|0), msPerBeat=60000/linkState.bpm;
  // leadMs is signed: + fires earlier (fixture lag), - fires later (Sonos line-in delay). Pick the next
  // grid beat whose OFFSET fire time is still ahead -- so a late offset still fires a just-passed beat,
  // and an early offset never fires a beat "immediately" at the wrong moment.
  const target=Math.ceil((beatNow + linkFire.leadMs/msPerBeat + 1e-6)/n)*n;
  const msAway=((target-beatNow)*msPerBeat) - linkFire.leadMs;
  linkFireTimer=setTimeout(function(){
    if(!linkStale()) fireLinkBeat();   // re-check at fire time -- the Pi could have gone quiet mid-wait
    scheduleNextLinkBeat();
  }, Math.max(5, msAway));
}
function fireLinkBeat(){
  const writes=[], decayWrites=[];
  if(linkFire.target==='strobe'||linkFire.target==='both'){
    writes.push(...strobeColorWrites(),[BRIDGE_STROBE_U,BRIDGE_STROBE_DIM_A,255],[BRIDGE_STROBE_U,BRIDGE_STROBE_FLASH_A,0]);   // 01g: one pulse
    decayWrites.push([BRIDGE_STROBE_U,BRIDGE_STROBE_DIM_A,0],[BRIDGE_STROBE_U,BRIDGE_STROBE_FLASH_A,0]);
  }
  if(linkFire.target==='laser'||linkFire.target==='both'){
    writes.push([BRIDGE_LASER_U,BRIDGE_LASER_CH1_A,49]);
    decayWrites.push([BRIDGE_LASER_U,BRIDGE_LASER_CH1_A,0]);
  }
  if(!writes.length) return;
  const touched=new Set(); writes.forEach(function(w){ setCh(w[0],w[1],w[2]); touched.add(w[0]); });
  touched.forEach(function(u){ sendU(u); });
  clearTimeout(linkFireDecayTimer);
  linkFireDecayTimer=setTimeout(function(){
    const t2=new Set(); decayWrites.forEach(function(w){ setCh(w[0],w[1],w[2]); t2.add(w[0]); });
    t2.forEach(function(u){ sendU(u); });
  }, 150);
}
// ---- Live show (26am): the Pi's live engine drives the strobe + both SlimPARs, PREDICTIVELY. The Pi sends a grid
// snapshot with every /bridgestate (~4x/s): beat length, time to the next beat, phrase position, groove mode (heavy /
// hats / kick / none), strobe level, kick present, wash index + time to its next change. The controller schedules each
// flash / colour change at the predicted time minus latencyMs (the audio-in -> detection -> network -> DMX -> fixture
// chain, measured once at the rig), so it lands WITH the kick instead of ~60-120 ms after it. Drop hits arrive as
// /livecue (reactive: confirmed on the Pi). Off by default; while ON, the reactive band targets (/bridgehit) pause.
const DESK_FRESH = DESKMODE && !fs.existsSync(LIVESHOW_FILE);   // 12u (before load() writes the defaults)
let liveCfg = load(LIVESHOW_FILE, { enabled:false, latencyMs:80 });
if(liveCfg.strobe!=='full' && liveCfg.strobe!=='drops') liveCfg.strobe='drops';   // 27s (kept for older clients)
if(!(liveCfg.level>=0 && liveCfg.level<=4)) liveCfg.level=liveCfg.strobe==='full'?4:2;   // 27w: strobe level, default 2
if(!liveCfg.int16n){ liveCfg.int16n=1; if((liveCfg.level|0)===0) liveCfg.level=1; if(liveCfg.level===2) liveCfg.level=3; try{ fs.writeFileSync(LIVESHOW_FILE, JSON.stringify(liveCfg,null,2)); }catch(e){} }   // 16n: INTENSITY OFF / LO / MED / HI = 0 / 1 / 3 / 4 -- a Controller sitting at 0 (last night) wakes up at LO, not dark; 2 -> MED
// 05u ENERGY FADER (Mike): how hard the AUTOMATIC show breathes. 50 = today's show. Below: the auto strobe steps down to off,
// the PAR pulse flattens toward a steady glow, the laser energy channels stay low. Above: auto strobe up to one level higher,
// deeper PAR pulses, laser energy toward its peak. Manual controls (pads, blackout, white-out, colour keys, chase, laser pads,
// manual strobe) are never scaled.
if(!(liveCfg.vibe>=0 && liveCfg.vibe<=100)) liveCfg.vibe=50;
function vibeLevel(){ const v=liveCfg.vibe, b=liveCfg.level|0; if(v>=50) return Math.min(4, b+(v>=75?1:0)); return Math.max(0, b-Math.round((50-v)/50*4)); }
const PAR_DEPTH=[0,0.5,1,1,1.6];   // 16n
function vibeK(){ const v=liveCfg.vibe; return v<50 ? 0.3+0.7*(v/50) : 1+0.6*((v-50)/50); }   // PAR pulse depth: 0.3 (steady) .. 1 .. 1.6 (deep)
let vibeAvg=null;
if(['off','drops','routine','engine','moments'].indexOf(liveCfg.laserMode)<0) liveCfg.laserMode='routine';   // 15b + engine (ALWAYS-ON)   // 28a
if(!liveCfg.engDef){ liveCfg.engDef=1; liveCfg.laserMode='engine'; }
if(liveCfg.laserMode==='engine') liveCfg.laserMode='moments';   // 15w: ALWAYS-ON is gone (Mike 10-16: 'too much and will never be a viable option') -- MOMENTS replaces it
function lzEngMode(){ return liveCfg.laserMode==='engine' || liveCfg.laserMode==='moments'; }   // 15w: both run through the engine's tiers   // 15h: ALWAYS-ON is the default laser (once; DROPS stays one tap away)
if(DESKMODE){ liveCfg.enabled=true; if(DESK_FRESH) liveCfg.laserMode='moments'; }   // 12u DESK: the show is ON at every start (nothing reaches a Rig); a fresh desk folder starts on laser DROPS
if(typeof liveCfg.djDrops!=='boolean') liveCfg.djDrops=false;
if(typeof liveCfg.stemMirror!=='boolean') liveCfg.stemMirror=false;   // 19a STEM MIRROR: read the stems off the AirPlay mirror on this PC (CC > READER > READ FROM)
if(typeof liveCfg.stemMirrorDelay!=='number') liveCfg.stemMirrorDelay=150;   // 19a: iPad screen -> UxPlay window, ms
if(typeof liveCfg.stemDrops!=='boolean') liveCfg.stemDrops=false;   // 17c STEM DROPS: the iPad stem reader's drops fire the show (off until Mike has tried it)
if(typeof liveCfg.waveDrops!=='boolean') liveCfg.waveDrops=true;   // 12k WAVE DROPS: the drop read off djay's scrolling waveform (on by default)
if(!(liveCfg.waveLagMs>=0 && liveCfg.waveLagMs<=3000)) liveCfg.waveLagMs=1400;
if(['dark','glow','beat'].indexOf(liveCfg.vocalBar)<0) liveCfg.vocalBar='dark';
if(!liveCfg.autoStab || typeof liveCfg.autoStab!=='object') liveCfg.autoStab={amt:'full', allow:'qesd'}; if(['off','light','full'].indexOf(liveCfg.autoStab.amt)<0) liveCfg.autoStab.amt='full'; liveCfg.autoStab.allow=String(liveCfg.autoStab.allow==null?'qesd':liveCfg.autoStab.allow).replace(/[^qesd]/g,'');   // 12r AUTO STABS (DROPS mode): the blackout hand on the kit's builds + drops   // 12l VOCAL BAR: when the bar before a drop empties out (the one-bar vocal), dark for that bar / a dim glow + dark last beat / just the last beat   // 12k: starting guess for how far the mirrored picture runs behind the sound (10-07 measured ~1.3-1.5 s); refined live
if(typeof liveCfg.djEq!=='boolean') liveCfg.djEq=false;   // 06d DJAY EQ events (bass kill / bass swap)
if(typeof liveCfg.cues!=='boolean') liveCfg.cues=false;
if(typeof liveCfg.djGrid!=='boolean') liveCfg.djGrid=true;   // 05d: djay (via the reader) drives the auto show's clock + sections when it can   // 05b CUES master switch (off by default)   // 03t STAGE D: marked drops from the djay reader fire the show's drop (off by default)
if(!(liveCfg.djLagMs>=0 && liveCfg.djLagMs<=1000)) liveCfg.djLagMs=150;   // 03t: how far the mirrored screen runs behind the audio
if(['off','dim','warm'].indexOf(liveCfg.idleGlow)<0) liveCfg.idleGlow='off';
if(!(liveCfg.parMax>=5 && liveCfg.parMax<=100)) liveCfg.parMax=100;
if(!(liveCfg.colBal>=0 && liveCfg.colBal<=100)) liveCfg.colBal=70;   // 08e COLOUR BALANCE strength (0 = raw palette)
if(['off','sensitive'].indexOf(liveCfg.buildDetect)<0) liveCfg.buildDetect='off';   // 28u
if(typeof liveCfg.parSplit!=='boolean') liveCfg.parSplit=false;   // 28v PAR split looks, OFF by default
if(typeof liveCfg.blackDrop!=='boolean') liveCfg.blackDrop=true;   // 28v: letting go of BLACKOUT fires the drop
const EN_RATES={off:0, '1/2':2, '1/4':1, '1/8':0.5, '1/16':0.25};   // beats between strobe hits while an ENERGY pad is held
if(!liveCfg.energy || typeof liveCfg.energy!=='object') liveCfg.energy={};
