t1=mk(); var bl1=t1[0], bl1x=t1[1]; t1=mk(); var bl2=t1[0], bl2x=t1[1]; t1=mk(); var pad=t1[0], padx=t1[1]; pad.width=320; pad.height=230; t1=mk(); var trc=t1[0], trx=t1[1]; t1=mk(); var blh=t1[0], blhx=t1[1]; t1=mk(); var ble=t1[0], blex=t1[1];   /* bloom chain halves 1/2 > 1/4 > 1/8 > 1/16: single big jumps skipped thin lines and beaded them */
