/* ======================= camera ======================= */
var R,U,Fw;
function camBasis(){ var y=(cam.yaw+camOff.yaw)*D2R, p=(cam.pitch+camOff.pitch)*D2R;
  Fw=[-Math.sin(y)*Math.cos(p), Math.sin(p), -Math.cos(y)*Math.cos(p)];
  var rx=-Fw[2], rz=Fw[0], rl=Math.hypot(rx,rz)||1; R=[rx/rl,0,rz/rl];
  U=[R[1]*Fw[2]-R[2]*Fw[1], R[2]*Fw[0]-R[0]*Fw[2], R[0]*Fw[1]-R[1]*Fw[0]];
  F=(Math.min(W,H)/2)/Math.tan(cam.hfov/2*D2R); }   /* sized by the shorter side: turning the phone keeps the same framing */
function toCam(p){ var dx=p[0]-cam.x, dy=p[1]-cam.y, dz=p[2]-cam.z; return [dx*R[0]+dy*R[1]+dz*R[2], dx*U[0]+dy*U[1]+dz*U[2], dx*Fw[0]+dy*Fw[1]+dz*Fw[2]]; }
var NEAR=0.08;
function projC(c){ return [W/2+F*c[0]/c[2], H/2-F*c[1]/c[2]]; }
function proj(p){ var c=toCam(p); return c[2]<NEAR?null:projC(c); }
function seg(a,b){ var A=toCam(a), B=toCam(b), t; if(A[2]<NEAR && B[2]<NEAR) return null;
  if(A[2]<NEAR){ t=(NEAR-A[2])/(B[2]-A[2]); A=[A[0]+(B[0]-A[0])*t, A[1]+(B[1]-A[1])*t, NEAR]; }
  if(B[2]<NEAR){ t=(NEAR-A[2])/(B[2]-A[2]); B=[A[0]+(B[0]-A[0])*t, A[1]+(B[1]-A[1])*t, NEAR]; }
  return [projC(A), projC(B), A[2], B[2]]; }
/* polygon clipped against the near plane (so big floors/ceilings work when they pass behind the camera) */
function polyPath(pts){ var C=pts.map(toCam), out=[], i, n=C.length;
  for(i=0;i<n;i++){ var a=C[i], b=C[(i+1)%n], ina=a[2]>=NEAR, inb=b[2]>=NEAR; if(ina) out.push(a);
    if(ina!==inb){ var t=(NEAR-a[2])/(b[2]-a[2]); out.push([a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, NEAR]); } }
  if(out.length<3) return null; var P=new Path2D(); out.forEach(function(q,j){ var s=projC(q); if(j) P.lineTo(s[0],s[1]); else P.moveTo(s[0],s[1]); }); P.closePath(); return P; }
