  /* ceiling planes (cut away in the overhead view) */
  var ridge=PX-PZ/2, top=PLATE+K*PZ/2;
  if(!over){
    addSurf(poly(c,[[-PX,PLATE,0],[PX,PLATE,0],[ridge,top,PZ/2],[-ridge,top,PZ/2]],'#0d0c14'),{par:0.30,strobe:0.45,gov:0.35,edge:[[0,PLATE,0],[0,top,PZ/2]]});
    addSurf(poly(c,[[-PX,PLATE,PZ],[PX,PLATE,PZ],[ridge,top,PZ/2],[-ridge,top,PZ/2]],'#0b0a11'),{par:0.08,strobe:0.25,gov:0.35,edge:[[0,PLATE,PZ],[0,top,PZ/2]]});
    addSurf(poly(c,[[-PX,PLATE,0],[-PX,PLATE,PZ],[-ridge,top,PZ/2]],'#0c0b12'),{par:0.18,strobe:0.35,gov:0.35,edge:[[-PX,PLATE,PZ/2],[-ridge,top,PZ/2]]});
    addSurf(poly(c,[[PX,PLATE,0],[PX,PLATE,PZ],[ridge,top,PZ/2]],'#0c0b12'),{par:0.18,strobe:0.35,gov:0.35,edge:[[PX,PLATE,PZ/2],[ridge,top,PZ/2]]});
    for(var x=-PX+0.61;x<PX;x+=0.61){ var zz=Math.min(PZ/2, PZ/2-Math.max(0,Math.abs(x)-ridge)); line3(c,[x,PLATE,0],[x,ceilY(x,zz-0.001),zz],'#17151f',1.2); line3(c,[x,PLATE,PZ],[x,ceilY(x,PZ-zz+0.001),PZ-zz],'#141219',1.2); }
    for(var zq=0.61;zq<PZ-0.3;zq+=0.61){ var ee=Math.min(zq,PZ-zq); line3(c,[-PX,PLATE,zq],[-PX+ee-0.001,ceilY(-PX+ee-0.001,zq),zq],'#16141d',1.2); line3(c,[PX,PLATE,zq],[PX-ee+0.001,ceilY(PX-ee+0.001,zq),zq],'#16141d',1.2); }   /* 14q: the side faces have rafters too */
    for(var dq=0.15;dq<PZ/2-0.05;dq+=0.15){ var yq=PLATE+K*dq, xq=PX-dq; line3(c,[-xq,yq,dq],[xq,yq,dq],'rgba(255,255,255,0.025)',1); line3(c,[-xq,yq,PZ-dq],[xq,yq,PZ-dq],'rgba(255,255,255,0.02)',1); line3(c,[-xq,yq,dq],[-xq,yq,PZ-dq],'rgba(255,255,255,0.022)',1); line3(c,[xq,yq,dq],[xq,yq,PZ-dq],'rgba(255,255,255,0.022)',1); }   /* 14q: tongue-and-groove boards */
    line3(c,[-PX,PLATE,0],[-ridge,top,PZ/2],'#1d1a27',2); line3(c,[PX,PLATE,0],[ridge,top,PZ/2],'#1d1a27',2); line3(c,[-PX,PLATE,PZ],[-ridge,top,PZ/2],'#1d1a27',2); line3(c,[PX,PLATE,PZ],[ridge,top,PZ/2],'#1d1a27',2); line3(c,[-ridge,top,PZ/2],[ridge,top,PZ/2],'#1d1a27',2.4);
  } else {
    [[-PX,PLATE,0],[PX,PLATE,0],[PX,PLATE,PZ],[-PX,PLATE,PZ]].forEach(function(p,i,a){ line3(c,p,[ridge*(p[0]>0?1:-1),top,PZ/2],'#2a2638',1); line3(c,p,a[(i+1)%4],'#2a2638',1); }); line3(c,[-ridge,top,PZ/2],[ridge,top,PZ/2],'#2a2638',1);
  }
  /* headers (white vinyl, dark at night) + posts */
  [[[-PX-0.1,HDR_LO,0.07],[PX+0.1,HDR_LO,0.07],[PX+0.1,PLATE,0.07],[-PX-0.1,PLATE,0.07]],[[-PX-0.1,HDR_LO,PZ-0.07],[PX+0.1,HDR_LO,PZ-0.07],[PX+0.1,PLATE,PZ-0.07],[-PX-0.1,PLATE,PZ-0.07]],
   [[-PX+0.07,HDR_LO,0],[-PX+0.07,HDR_LO,PZ],[-PX+0.07,PLATE,PZ],[-PX+0.07,PLATE,0]],[[PX-0.07,HDR_LO,0],[PX-0.07,HDR_LO,PZ],[PX-0.07,PLATE,PZ],[PX-0.07,PLATE,0]]].forEach(function(q){ addSurf(poly(c,q,'#1a1a24'),{par:0.55,strobe:0.8,gov:0.25}); });
  addSurf(poly(c,[[-PX-0.1,HDR_LO,0.07],[PX+0.1,HDR_LO,0.07],[PX+0.1,HDR_LO,-0.07],[-PX-0.1,HDR_LO,-0.07]],'#121219'),{par:0.3,strobe:0.5,gov:0.1});
  [[-1,0],[1,0],[-1,PZ],[1,PZ]].forEach(function(q){ var x=q[0]*PX, z=q[1]; addSurf(poly(c,[[x-0.08,0,z+0.08],[x+0.08,0,z+0.08],[x+0.08,HDR_LO,z+0.08],[x-0.08,HDR_LO,z+0.08]],'#16161f'),{par:z?0.15:0.5,strobe:0.7,gov:0.1}); });
  poly(c,[[-1.55,HDR_LO-0.12,0.02],[1.55,HDR_LO-0.12,0.02],[1.55,HDR_LO,0.02],[-1.55,HDR_LO,0.02]],'#0f0f15');   /* retracted screen case */
