function momLvl(o){ var l=o.lvl==null?3:(o.lvl==='p'?1:Math.max(0,Math.min(4,o.lvl|0))); return l?MOM_LVL[l]:null; }
function momLook(L, bt, gi){ var ch={}, i; for(i=1;i<=34;i++) ch[i]=0; var fr=function(x){ return x-Math.floor(x); }, ph=fr(bt), k=Math.floor(bt), per=L.per||0, n=L.sh.length;
  var at=function(q){ return L.sh[(((per?Math.floor(q/per):0)+(gi|0))%n+n)%n]; };
  ch[1]=KIT_ON; ch[3]=240; ch[4]=at(k); ch[12]=0;   /* native colours */
  if(per && n>1 && ph>0.92 && at(k+1)!==ch[4]){ ch[1]=0; ch[4]=at(k+1); }   /* the next shape preloads in a dark 1/12 */
  var mv=L.mv;
  if(mv==='spin') ch[6]=Math.floor(fr(bt/8)*128); else if(mv==='spinfast') ch[6]=Math.floor(fr(bt/4)*128);
  else if(mv==='flip'){ var d=Math.floor(bt/4)%2?-1:1; ch[6]=((Math.floor(fr(bt/4)*128)*d)%128+128)%128; }
  else if(mv==='turn') ch[6]=(k%4)*32;
  else if(mv==='sweep') ch[8]=KIT_SW[Math.min(KIT_SW.length-1, Math.floor(fr(bt/4)*KIT_SW.length))];
  else if(mv==='draw') ch[14]=Math.round(8+128*Math.min(1,bt/2));
  if(L.sz==='burst') ch[5]=ph<0.15?Math.round(110*(1-ph/0.15)):0; else if(L.sz==='grow') ch[5]=Math.round(110*(1-Math.min(1,bt/4)));
  if(L.clap && k%2===1 && ph<0.12) ch[12]=KIT_WHITE;   /* claps flick it white */
  if(L.stab && !kitGate(L.stab,ph)) ch[1]=0; return ch; }
function momNextHit(st){ return MOM_HIT[(st.n|0)%MOM_HIT.length].n; }
function lzMom(o, st){ var z={}, i; for(i=1;i<=34;i++) z[i]=0; var now=+o.now||0, dt=(st.t!=null && now>st.t && now-st.t<1)?now-st.t:0; st.t=now;
  var P=momLvl(o); if(!P){ st.air=(st.air||0)*(1-Math.min(1,dt/300)); st.name=null; st.kind=null; st.hit=null; st.pun=null; ENG.look='dark'; ENG.tier=o.tier; return z; }   /* 16n INTENSITY OFF = dark */
  if(st.n==null) st.n=0; var ch=null, nm=null, kind=null, b=+o.b||0, pk=Math.min(+o.pkLen||32, 4*P.dropBars), over=(st.air||0)>P.cap;
  if(o.tier==='peak' && o.since>=0 && o.since<pk){ var bt=o.since; kind='drop'; st.hit=null; st.pun=null; st.lastEnd=b+(pk-bt);
    if(bt<1){ ch=kitFrame0({ph:'drop', b:bt}); nm='THE 1'; }
    else { var q=bt-1, hb4=4*P.heroBars, L=MOM_DROP[(((o.dropIdx|0)+Math.floor(q/hb4))%MOM_DROP.length+MOM_DROP.length)%MOM_DROP.length]; ch=momLook(L, q, 0); nm=L.n;
      var ck=Math.floor(q/(4*P.colBars)); if(ck%2===1){ var KC=KIT_COLS[(((ck>>1)+(o.dropIdx|0))%6+6)%6]; if(!(L.clap && ch[12])) ch[12]=KC[0]; nm=L.n+' · '+KC[2]; }   /* 16n: native <-> a solid colour every colBars */
      if(q%hb4>hb4-0.08 && bt<pk-1) ch[1]=0; }   /* 16n: the next hero loads in the dark, so it SNAPS in on the bar */
    if(bt>pk-0.06) ch[1]=0; }
  else if(o.tier==='lift' && o.left>0 && o.left<=4*P.buildBars){ ch=kitFrame0({ph:'build', b:o.left, len:4*P.buildBars, col:o.col, dark:o.dark}); nm='BUILD'; kind='build'; st.hit=null; st.pun=null; }
  else { if(st.hit && (b>=st.hit.b0+st.hit.L.bars*4 || b<st.hit.b0-8)) st.hit=null; if(st.pun && (b>=st.pun.b0+st.pun.n || b<st.pun.b0-8)) st.pun=null;
    var b0=Math.floor(b/4)*4, line=(o.tier==='groove' || o.tier==='peak') && o.pb===0 && b-b0<1.5 && o.phrase!==st.lastPh && (o.K==null || o.K>0.25);
    if(!st.hit && st.force){ st.hit={L:MOM_HIT[(st.n++)%MOM_HIT.length], b0:Math.ceil(b/4-1e-6)*4}; st.force=false; st.lastPh=o.phrase; }
    else if(!st.hit && line && P.hitGap && !over && o.E>P.hitE && (st.lastEnd==null || b-st.lastEnd>=P.hitGap || b<st.lastEnd-256)){
      st.hit={L:MOM_HIT[(st.n++)%MOM_HIT.length], b0:b0}; st.lastPh=o.phrase; }
    else if(!st.hit && !st.pun && line && P.pun && !over){ st.pn=(st.pn|0)+1; st.pun={L:MOM_HIT[(st.pn+3)%MOM_HIT.length], b0:b0, n:P.pun}; st.lastPh=o.phrase; }   /* 16n PHRASE CHANGE: a 1 (MED) / 2 (HI) beat flash of a hit look on the line */
    if(st.hit && b>=st.hit.b0){ var hb=b-st.hit.b0, HL=st.hit.L.bars*4; ch=momLook(st.hit.L, hb, 0); nm=st.hit.L.n; kind='hit'; if(hb>HL-0.06) ch[1]=0; st.lastEnd=st.hit.b0+HL; }
    else if(st.pun && b>=st.pun.b0){ var pq=b-st.pun.b0; ch=momLook(st.pun.L, pq, 0); nm=st.pun.L.n; kind='phrase'; if(pq>st.pun.n-0.06) ch[1]=0; } }
  if(ch && o.dark){ ch[1]=0; ch[18]=0; }
  var on=!!(ch && ch[1]>0); st.air=(st.air||0)+((on?1:0)-(st.air||0))*Math.min(1,dt/300); st.name=nm; st.kind=kind;
  ENG.look=nm||'dark'; ENG.tier=o.tier; return ch||z; }
/*KIT-END*/

/* 12o REAL-LASER RENDERER: draws the laser from its DMX channels (the same 34 values the controller sends), modelled on the 10-12 catalog
   films: each head draws the pattern in its own window (14 deg half-width), the two heads side by side (13d: MIRRORED -- head 2 = head 1 flipped, the 10-13 film), head 2 sits a
   little higher (the physical stagger the ALIGN film found). B7 = a circle per head, B0 = a flat line per head, B40 = the L (a stroke
   with an arm), B114 = Quickshot's zigzag; the rest draw as circles. */
var KIT_W=14, KIT_STAGGER=1.2;
function kitMove(v){ v=v%64; return (v<=32?v:v-64)/32; }   /* 0 centre, 32 one edge, 40 the other edge, back by 63 */
