  if(mode==='track' && A && A.cues){ var CC={strobe:'#ffffff',black:'#000000',pars:'#ffb000',hit:'#ff3b3b',laser:'#b06bff',fog:'#9aa1ab',hold:'#38b6ff'}; A.cues.forEach(function(q){ var x=x0(q.t/1000), wq=Math.max(2*d,x0(Math.max(0,+q.len||0)*A.L/1000)); c.fillStyle=CC[q.type]||'#fff'; c.fillRect(x,h-5*d,wq,4*d); }); }   /* your cues along the bottom edge */
