var tWall0=performance.now(), TRL={last:0}, CURLOOK='', FASTLOOK={rapid:1,spin:1,cross:1,open:1,'kit:sweep':1,'kit:whip':1,'kit:quick':1};   /* trails only where the real unit smears: fast moves. FANS etc. stay razor sharp */
var lastF=0;
