  [].forEach.call(document.querySelectorAll('[data-upa]'),function(b){ var a=arc[+b.dataset.upa]; b.addEventListener('click',function(){ if(!confirm('Go back to build '+a.build+'?'+(j.show?'\n\nThe show is ON \u2014 lights pause for 2\u20133 s while it restarts.':''))) return; upSend('/admin/rollback', JSON.stringify({archive:a.file}), 'application/json', a.build); }); });
