  if(act==='rplrig'){ if(!confirm('Play this session on the REAL lights? The live show takes over again when you STOP.')) return; return rcRpl({act:'start', id:id, rig:true, tape:rcTp(x, key)}).then(function(){ window.scrollTo(0,0); rcLoad(); }); }
