var MIXEXT=['m4a','mp3','wav','aac','aiff','flac','caf','ogg','opus'], MIXT={'audio/mp4':'m4a','audio/x-m4a':'m4a','audio/m4a':'m4a','audio/mpeg':'mp3','audio/mp3':'mp3','audio/wav':'wav','audio/x-wav':'wav','audio/wave':'wav','audio/aac':'aac','audio/aiff':'aiff','audio/x-aiff':'aiff','audio/flac':'flac','audio/x-flac':'flac','audio/x-caf':'caf','audio/ogg':'ogg','audio/opus':'opus'};
