  (RC.mixes||[]).forEach(function(m){ var p=m.stage==='listen'?0.1+0.4*(m.p||0):m.stage==='show'?0.5+0.45*(m.p||0):m.stage==='laser'?0.97:0.08;
    h+='<div class="rcRow rcMix"><div class="rcTxt"><b>'+(m.stage==='error'?'<span style="color:#ff8a8a">MIX IMPORT FAILED</span>':'IMPORTING MIX')+'</b><small>'+esc(m.file||m.id)+' · '+(m.stage==='error'?esc(m.error||''):esc(st[m.stage]||m.stage)+(m.stage==='listen'||m.stage==='show'?'\u00a0'+Math.round(100*(m.p||0))+'\u00a0%':''))+'</small>'+
      (m.stage==='error'?'<div class="rcAct" style="margin-top:8px"><a class="sbtn" href="/rec/mix?listen='+esc(m.id.slice(4))+'&here=1" style="color:var(--amb)">LISTEN ON THIS DEVICE</a><button class="sbtn" data-mixdis="'+esc(m.id)+'">DISMISS</button></div>':'<div class="rcPb"><div style="width:'+Math.round(100*p)+'%"></div></div>')+'</div></div>'; });
