  part(2,'COMBOS');
  [['slow',196],['fast',222]].forEach(([sp,v])=>{ [['R',[6]],['X',[7]],['Y',[8]],['R+X',[6,7]],['R+Y',[6,8]],['X+Y',[7,8]],['R+X+Y',[6,7,8]]].forEach(([nm,chs],i)=>{ const m={}; chs.forEach(c=>m[c]=v);
      add(5000,O(Lsh,{12:BANDS[i%7]},m),'COMBO '+nm+' '+sp+' ('+chs.map(c=>'CH'+c+' '+v).join(', ')+', B40 L '+NM[BANDS[i%7]]+')','combo '+sp); add(300,null,'dark','combo '+sp); }); });
  [['R+X wave',{6:200,7:140}],['R+Y wave',{6:200,8:140}],['X wave+Y wave',{7:140,8:170}],['R+X wave+Y move',{6:200,7:140,8:200}]].forEach(([nm,m],i)=>{ add(5000,O(Ln,{12:BANDS[(i+3)%7]},m),'COMBO '+nm+' ('+Object.keys(m).map(c=>'CH'+c+' '+m[c]).join(', ')+', B0 line)','combo waves'); add(300,null,'dark','combo waves'); });
