const LINKCTL_FILE = path.join(__dirname, 'link-ctl.json');
let linkCtl={want:true, bridge:true}; try{ linkCtl=Object.assign(linkCtl, JSON.parse(fs.readFileSync(LINKCTL_FILE,'utf8'))); }catch(e){} linkCtl.want=false;   // 15d: LINK RETIRED (Mike 10-15) -- the djay clock (Reader), the Pi's tempo and HANDS cover it; the code stays, switched off
let linkAgent={running:null, log:'', t:0};
let bridgeAgent={running:null, t:0}, bridgeHold=0;   // 27q bridgeHold: until when the supervisor leaves a page YOU closed alone   // 26r: the Pi supervisor also reports whether the bridge page (Chromium) is open
// Tracks tab: audio files (TRACK_TYPES) in tracks/ next to the controller. Each track's analysis is a recording-format file in logs/ whose
// id is a stable hash of the file name (so re-analysing overwrites, and the id still matches the logs name pattern).
const TRACK_DIR = path.join(__dirname, 'tracks');
function trackNameOk(n){ return typeof n==='string' && n.length<200 && path.basename(n)===n && !n.startsWith('.') && !/[\\/]/.test(n) && !!TRACK_TYPES[trackExt(n)]; }
// Formats the browser decodes itself. FLAC/Ogg/Opus need a recent iOS; AIFF decodes in Safari but not Chrome -- the analyzer says so if decoding fails.
const TRACK_TYPES={mp3:'audio/mpeg', m4a:'audio/mp4', aac:'audio/aac', wav:'audio/wav', flac:'audio/flac', aif:'audio/aiff', aiff:'audio/aiff', ogg:'audio/ogg', opus:'audio/ogg'};
function trackExt(n){ const m=/\.([a-z0-9]+)$/i.exec(String(n)); return m?m[1].toLowerCase():''; }
function trackId(n){ const h=s=>{ let x=0x811c9dc5; for(const c of Buffer.from(s,'utf8')){ x^=c; x=Math.imul(x,0x01000193)>>>0; } return x; };
  return 'track-'+String(h(n)%1e8).padStart(8,'0')+'-'+String(h('#'+n)%1e6).padStart(6,'0'); }
function trackAudioUrl(fp){   // audio for a track analysis = the file it came from
  try{ const fd=fs.openSync(fp,'r'), b=Buffer.alloc(4096), n=fs.readSync(fd,b,0,4096,0); fs.closeSync(fd);
    const st=JSON.parse(b.toString('utf8',0,n).split('\n')[0]);
    if(st.src==='track' && trackNameOk(st.track) && fs.existsSync(trackPath(st.track))) return '/tracks/'+encodeURIComponent(st.track);
  }catch(e){} return null; }
