      if(!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR);
      if(d.events.length) aAppend(path.join(LOG_DIR, d.id+'.ndjson'), d.events.map(e=>JSON.stringify(e)).join('\n')+'\n');   // 01n: non-blocking
      res.writeHead(200,{'Content-Type':'application/json'}); res.end('{"ok":true}');
