      if(audioLastSeq[id]!==undefined && seq<=audioLastSeq[id]){ res.writeHead(200,{'Content-Type':'application/json'}); res.end('{"ok":true,"dup":true}'); return; }
      if(!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR);
      aAppend(path.join(LOG_DIR, id+'.'+ext), buf); audioLastSeq[id]=seq;   // 01n: non-blocking
      res.writeHead(200,{'Content-Type':'application/json'}); res.end('{"ok":true}');
