      marks.push({id:++markSeq, label:d.label, at:Date.now()}); if(marks.length>50) marks.shift();
      const rec=!!(bridgeState.recording && bridgeState.t && Date.now()-bridgeState.t<5000);
      res.writeHead(200,{'Content-Type':'application/json'}); res.end(JSON.stringify({ok:true, recording:rec, rid:rec?bridgeState.rid:null}));
