      if(req.method==='POST' && u==='/rec/mix/listen'){ const sid=String(q.get('id')||'').replace(/^mix-/,''); if(q.get('here')==='1'){ const L=MX.last[sid]; if(!L || !L.ext) throw new Error('upload the audio first'); mxKill(sid); Object.assign(L,{stage:'listen', p:0, error:null, dismissed:false, browser:'this device', seen:Date.now(), msg:'listening on the phone / computer'}); return J(200,{ok:true}); } return J(200, mxListen(sid)); }   /* 16g / 16i here=1 */   /* 16g */
      if(req.method==='POST' && u==='/rec/mix/progress'){ const b=JSON.parse(await readBody(req)||'{}'), L=MX.last[String(q.get('id')||'').replace(/^mix-/,'')]; if(L && L.stage==='listen'){ L.seen=Date.now(); if(b.p!=null) L.p=+b.p; if(b.msg) L.msg=String(b.msg).slice(0,140); if(b.error){ L.stage='error'; L.error=String(b.error).slice(0,200); mxKill(String(q.get('id')||'').replace(/^mix-/,'')); } } return J(200,{ok:true}); }
      if(req.method==='POST' && u==='/rec/mix/dismiss'){ const L=MX.last[String(q.get('id')||'').replace(/^mix-/,'')]; if(L && L.stage==='error') L.dismissed=true; return J(200,{ok:true}); }
