      if(req.method==='GET' && u==='/rec/mix/status') return J(200, mxStatus(String(q.get('id')||'').replace(/^mix-/,'')));
      if(req.method==='POST' && u==='/rec/rerender'){ const b=JSON.parse(await readBody(req)||'{}'); kid('session', b.id); return J(200, rrStart(b.id)); }   /* 16d */
