    const u=req.url.split('?')[0], q=new URLSearchParams(req.url.split('?')[1]||''), ok=d=>/^rec-[0-9]{8}-[0-9]{6}$/.test(d||'') && fs.existsSync(path.join(DJAY_DIR(),d));
    if(u==='/lab/sesdata'){ const d=q.get('dir'), r=q.get('rec')||''; if(!ok(d) || !/^[a-z]+-\d{8}-\d{6}\.ndjson$/.test(r)){ res.writeHead(400,{'Content-Type':'application/json'}); res.end('{"error":"bad dir/rec"}'); return; }
      res.writeHead(200,{'Content-Type':'application/json','Cache-Control':'no-store'}); res.end(JSON.stringify(sesData(d, r))); return; }
    let m=/^\/lab\/truth\/(rec-[0-9]{8}-[0-9]{6})$/.exec(u); if(m && ok(m[1])){ res.writeHead(200,{'Content-Type':'application/json','Cache-Control':'no-store','Content-Disposition':'attachment; filename="'+m[1].slice(4)+'-truth.json"'}); res.end(JSON.stringify(sesTruth(m[1]),null,1)); return; }
    m=/^\/lab\/sesframe\/(rec-[0-9]{8}-[0-9]{6})\/(f-[0-9]+\.jpg)$/.exec(u); if(m && ok(m[1])){ const fp=path.join(DJAY_DIR(),m[1],m[2]); if(fs.existsSync(fp)){ res.writeHead(200,{'Content-Type':'image/jpeg','Cache-Control':'max-age=86400'}); fs.createReadStream(fp).pipe(res); return; } }
