$('rCopy').onclick=function(){ var L=inRange(); if(!L){ msg('Set IN and OUT (or THIS PHRASE) first.'); return; } if(!L.length){ msg('No cues in the range.'); return; } CLIP=rel(L); rngTxt(); msg('Copied '+CLIP.length+' cue'+(CLIP.length===1?'':'s')+' \u2014 move the playhead and PASTE.'); };
$('rPaste').onclick=function(){ if(!CLIP){ msg('Nothing copied yet.'); return; } mut({op:'paste', t:Math.round(snapT(CUR,+$('snap').value)), cues:CLIP}).then(function(j){ if(j&&j.added) msg('Pasted '+j.added.length+' at bar '+fmtPos(snapT(CUR,+$('snap').value))+'.'); }); };
$('rDel').onclick=function(){ var L=inRange(); if(!L){ msg('Set IN and OUT (or THIS PHRASE) first.'); return; } if(!L.length){ msg('No cues in the range.'); return; } mut({op:'delmany', ids:L.map(function(c){ return c.id; })}).then(function(){ msg('Deleted '+L.length+' (UNDO brings them back).'); }); };
$('rSave').onclick=function(){ var L=inRange(); if(!L||!L.length){ msg('Set a range with cues in it first.'); return; } var n=(window.prompt('Template name (e.g. my drop):','')||'').trim(); if(!n) return;
  fetch('/lab/cuetpl',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'save', name:n, cues:rel(L)})}).then(function(r){ return r.json(); }).then(function(j){ if(j.ok){ TPL=j.templates; tplDraw(); msg('Saved template \u201c'+n+'\u201d ('+L.length+' cues).'); } else msg(j.error); }); };
function tplDraw(){ $('tpls').innerHTML=TPL.length?'<span style="font-size:11px;color:var(--dim)">TEMPLATES</span>'+TPL.map(function(t){ return '<button class="chip" type="button" data-tp="'+t.id+'">'+t.name.replace(/</g,'&lt;')+'<i data-tx="'+t.id+'">\u2715</i></button>'; }).join(''):'<span style="font-size:11px;color:var(--dim)">Templates: set a range, \u2605 SAVE TEMPLATE; then tap one to place it at the playhead.</span>'; }
$('tpls').addEventListener('click',function(e){ var x=e.target.closest('[data-tx]'), b=e.target.closest('[data-tp]');
  if(x){ if(window.confirm('Delete this template?')) fetch('/lab/cuetpl',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'del', id:x.dataset.tx})}).then(function(r){ return r.json(); }).then(function(j){ TPL=j.templates||[]; tplDraw(); }); return; }
  if(b){ var t=TPL.find(function(z){ return z.id===b.dataset.tp; }); if(t) mut({op:'paste', t:Math.round(snapT(CUR,+$('snap').value)), cues:t.cues}).then(function(j){ if(j&&j.added) msg('Placed \u201c'+t.name+'\u201d at bar '+fmtPos(snapT(CUR,+$('snap').value))+'.'); }); } });
fetch('/lab/cuetpl').then(function(r){ return r.json(); }).then(function(j){ TPL=j.templates||[]; tplDraw(); });
window.CE={get SEEKTO(){ return SEEKTO; }, folPoll:folPoll, get FOL(){ return FOL; }, get CUR(){ return CUR; }, open:function(c){ openSheet(c); }, openMark:function(m){ openMark(m); }, get MSEL(){ return MSEL; }, get RANGE(){ return RANGE; }, get CLIP(){ return CLIP; }, get HIST(){ return HIST; }, get LOOK(){ return LOOK; }, get D(){ return D; }, get CUES(){ return CUES; }, get SEL(){ return SEL; }, seek:seek, draw:draw, beatAt:beatAt, timeOf:timeOf, fmtPos:fmtPos, setPlay:function(p,t){ PLAY=p; if(t!=null) CUR=t; }, addCue:addCue, active:active};
load();
