  { const q=SES.rq||(SES.rq={n:0,ms:0,mx:0,t:Date.now()}), ms=+r.ms||0; q.n++; q.ms+=ms; q.mx=Math.max(q.mx,ms); if(Date.now()-q.t>=10000){ sesShow({t:Date.now(), kind:'rd', n:q.n, ms:Math.round(q.ms/q.n), mx:Math.round(q.mx), s:Math.round((Date.now()-q.t)/1000)}); SES.rq=null; } }   // 06p: reader speed per 10 s
