  const aud=x=>{ const d=(x.dk||[]).filter(k=>k&&k.st==='playing'); return d.length?d.map(k=>String(k.ti||'?').slice(0,28)+' @'+Math.round(+k.el||0)+'s').join(' + '):'-'; };
  const o=[], P=s=>o.push(s), quiet={djbar:1,rd:1,wash:1,col:1,lag:1,kit:1,ov:1};
  P('PACK REPORT '+(meta.id||'?')+' · build '+(meta.build||'?')+' · '+Math.round(((meta.t1||Date.now())-t0)/60000)+' min · '+L.length+' show events');
  P('notes: '+(meta.notes?String(meta.notes).replace(/\s+/g,' ').slice(0,600):'(none)')); P('');
