  const wv=K('wave drop'); P(''); P('5 WAVE DROPS fired '+wv.length+(wv.length?'':' (never)')); wv.forEach(x=>P('  '+mm(x.t)+'  '+String(x.track||'?').slice(0,40)+' '+(x.kind2||'')));
  const se=K('set'); P(''); P('6 SETTINGS CHANGED '+se.length); se.slice(0,80).forEach(x=>P('  '+mm(x.t)+'  '+x.k+' '+x.from+' -> '+x.to));
