  var fi=0;
  beats.forEach(function(bt){ var s=[0,0,0,0], n=0;
    while(fi<F.length && F[fi].t<bt.t) fi++;
    for(var j=fi;j<F.length && F[j].t<bt.t1;j++){ for(var q=0;q<4;q++) s[q]+=F[j].e[q]||0; n++; }
    bt.v=s.map(function(x){ return n?x/n:0; }); });
