  var S=trans.filter(function(t){ return t.strong; }), pS=peak(S), onPS=S.filter(function(t){ return near(t.pos,0); }).length;   // kick in/out: the unambiguous ones (risers fade in, so their start is fuzzy)
  var posAt=function(t){ var lo2=0, hi2=beats.length-1; while(lo2<hi2){ var m=(lo2+hi2+1)>>1; if(beats[m].t<=t+1) lo2=m; else hi2=m-1; } return beats[lo2]; };
  var MK=ev.filter(function(e){ return e.k==='m' && e.label!=='other'; }), mOn=MK.filter(function(m){ var b=posAt(m.t); return near(b.pos+(m.t-b.t)/(b.t1-b.t),0); }).length;
  var pc=function(x,y){ return y?Math.round(100*x/y):0; }, verdict;
