  h.push('Kick in/out: '+z.onPS+'/'+z.S+' on a phrase start ('+pc(z.onPS,z.S)+')'+(z.S?' \\u00b7 strongest position: beat '+(z.bestS+1)+' of 32':'')+'.');
  h.push('All transitions (incl. risers, fills) found without the phrase count: '+z.T+' \\u00b7 on a phrase start '+z.onP+' ('+pc(z.onP,z.T)+'), on a half-phrase '+z.onH+(z.best?' \\u00b7 strongest phrase position: beat '+(z.best+1)+' of 32':'')+'.');
  if(z.marks) h.push('Your marks on a phrase start: '+z.marksOn+'/'+z.marks+' ('+pc(z.marksOn,z.marks)+').');
