// --- Causal replay: re-run the phrase analysis step by step on ONLY the data up to each moment (what a live tracker
// would know), then score it against the full-file view and the user's drop marks. Roadmap step 2.
function causalReplay(onProg, done){
  var fin=TL.sec; if(!fin || !fin.bars.length) return done(null);
  var FB=fin.bars, beat=fin.barMs/4, dur=TL.dur;
  var E=TL.ev.filter(function(e){ return e.k!=='m' && typeof e.t==='number'; }).sort(function(a,b){ return a.t-b.t; });   // marks never leak in
  var M=TL.ev.filter(function(e){ return e.k==='m' && e.label==='drop'; }).map(function(e){ return e.t; }).sort(function(a,b){ return a-b; });
  var every=FB.length>400?2:1, steps=[], i;
  for(i=every-1;i<FB.length;i+=every) steps.push({T:FB[i].t1, lane:true});   // after each finished bar
  M.forEach(function(m){ for(var k=-8;k<=24;k++) steps.push({T:m+k*beat, m:m, k:k}); });   // beat by beat around each marked drop
  steps=steps.filter(function(s){ return s.T>0 && s.T<=dur; }).sort(function(a,b){ return a.T-b.T; });
  var calls=[], si=0, lane=[], pred={};
  function upto(T){ var lo=0, hi=E.length; while(lo<hi){ var m=(lo+hi)>>1; if(E[m].t<=T) lo=m+1; else hi=m; } return E.slice(0,lo); }
  function finAt(t){ var lo=0, hi=FB.length-1; while(lo<hi){ var m=(lo+hi+1)>>1; if(FB[m].t<=t) lo=m; else hi=m-1; } return FB[lo]; }
  (function step(){
    var t0=Date.now();
    while(si<steps.length && Date.now()-t0<40){
      var s=steps[si++], r=null, lb=null; try{ r=engine(upto(s.T)); }catch(e){}
      if(r && r.bars.length) for(var j=r.bars.length-1;j>=0;j--) if(r.bars[j].t1<=s.T+1){ lb=r.bars[j]; break; }
      if(r) r.drops.forEach(function(d){ if(!calls.some(function(c){ return Math.abs(c.d-d)<=4*beat; })) calls.push({d:d, at:s.T}); });
      if(s.lane){ var g={T:s.T, st:lb?lb.st:null, pbOk:false, bt:lb?lb.t:null, bt1:lb?lb.t1:null};   // bt/bt1: the live grid's last bar, for beat-aligned gating
        if(lb){ var fb=finAt(lb.t+beat/2); g.err=lb.t-fb.t; g.pbOk=Math.abs(g.err)<beat/2 && fb.pb===lb.pb; }   // same bar (within half a beat) and same phrase position as the full view; phase error kept separately
        lane.push(g); }
      if(s.k===-1 && lb) pred[s.m]={grid:Math.abs(lb.t+(9-lb.pb)*(lb.t1-lb.t)-s.m)<=beat/2, quiet:lb.st!=='G'};   // a beat before the drop: next phrase start per the live grid
    }
    onProg(si/steps.length);
    if(si<steps.length) setTimeout(step,0); else done(finish());
  })();
  function finish(){
    var lock=null; for(var q=lane.length-1;q>=0;q--){ if(!lane[q].pbOk){ lock=q+1<lane.length?lane[q+1].T:null; break; } if(q===0) lock=lane[0].T; }
    calls.forEach(function(c){ c.fresh=c.at-c.d<=32*beat;   // a call more than 8 bars late is a retroactive re-read, not a live call
      c.final=fin.drops.some(function(d){ return Math.abs(d-c.d)<=4*beat; }); c.fakeLater=fin.fakes.some(function(f){ return Math.abs(f-c.d)<=4*beat; });
      c.marked=M.some(function(m){ return Math.abs(m-c.d)<=8*beat; }); });
    var marks=M.map(function(m){ var c=null; calls.forEach(function(x){ if(Math.abs(x.d-m)<=8*beat && (!c || x.at<c.at)) c=x; }); return {m:m, lat:c?(c.at-m)/beat:null, pred:pred[m]||{}}; });
    var pe=lane.filter(function(g){ return g.pbOk; }).map(function(g){ return Math.abs(g.err); });
    // Gate simulation (26i): the kick strobe as it fires today (every kick-band hit) vs gated by the LIVE section view
    // (fire only while the live tracker believes the last finished bar was groove, only on its beats, and never twice
    // within 150 ms; 26ad: no view yet = dark).
    // Reference = the full-file view's bar states (hindsight): hits in break/build bars are unwanted.
    var KH=TL.ev.filter(function(e){ return e.k==='h' && laneOf(e)===0; }).map(function(e){ return e.t; }).sort(function(a,b){ return a-b; });
    var liveAt=function(t){ var lo=0, hi=lane.length-1, r=-1; while(lo<=hi){ var m=(lo+hi)>>1; if(lane[m].T<=t){ r=m; lo=m+1; } else hi=m-1; } return r<0?null:lane[r]; };
    var onBeat=function(t){ var g=liveAt(t); if(!g || g.bt===null) return false; var L=(g.bt1-g.bt)/4, ph=(((t-g.bt)%L)+L)%L; return Math.min(ph,L-ph)<=90; };
    var liveSt=function(t){ var lo=0, hi=lane.length-1, r=-1; while(lo<=hi){ var m=(lo+hi)>>1; if(lane[m].T<=t){ r=m; lo=m+1; } else hi=m-1; } return r<0?null:lane[r].st; };
    var finSt=function(t){ var b=finAt(t); return (t>=b.t && t<b.t1)?b.st:null; };
    var groove=function(s){ return s==='G' || s==='L'; };
    var gate={react:[], gated:[]}, lastR=-1e9, lastG=-1e9;
    KH.forEach(function(t){ var want=groove(finSt(t)), dbl=t-lastR<150; lastR=t;
      gate.react.push({t:t, want:want, dbl:dbl});
      // 26ad: fire only on the live grid's beats (+-90 ms: the kick band also fires on bass notes between beats) and only once
      // the live tracker has a view (was: behave like today for the first ~30 s -- every hit of a quiet, bass-heavy intro)
      var ls=liveSt(t), open=ls!==null && groove(ls) && onBeat(t), fire=open && t-lastG>=150; if(fire) lastG=t;
      var fb=finAt(t), FL=(fb.t1-fb.t)/4, fph=(((t-fb.t)%FL)+FL)%FL, onFull=Math.min(fph,FL-fph)<=90;   // missed = a wanted ON-BEAT kick (hindsight grid) the gate dropped
      gate.gated.push({t:t, want:want, fire:fire, missed:!fire && want && onFull && !dbl}); });
    return {T:steps.map(function(s){ return s.T; }), gate:gate, phaseMs:pe.length?median(pe):null, lane:lane, calls:calls, marks:marks, lock:lock, agree:lane.filter(function(g){ return g.pbOk; }).length/(lane.length||1), every:every, steps:steps.length};
  }
}
function czSummary(z){
  var h=['<b style="color:var(--ink)">Causal replay</b> (live simulation: each step sees only the audio up to that moment'+(z.every>1?'; every 2nd bar on long files':'')+'):'];
  h.push('Live phrase count '+(z.lock!=null?'right for good from '+fmt(z.lock):'never settles')+' \u00b7 agrees with the full-file count on '+Math.round(z.agree*100)+'% of bars'+(z.phaseMs!=null?' \u00b7 live beat phase vs full-file: typically '+Math.round(z.phaseMs)+' ms apart':'')+'.');
  if(z.marks.length){
    var got=z.marks.filter(function(x){ return x.lat!=null; }), lats=got.map(function(x){ return x.lat; });
    h.push('Your drops confirmed live: '+got.length+'/'+z.marks.length+(got.length?', typically '+median(lats).toFixed(0)+' beats after the 1 (worst '+Math.max.apply(null,lats).toFixed(0)+'; the floor is 4 \u2014 a bar has to finish)':'')+'.');
    var pg=z.marks.filter(function(x){ return x.pred.grid; }).length, pq=z.marks.filter(function(x){ return x.pred.grid && x.pred.quiet; }).length;
    h.push('Predictable on the 1: live phrase grid pointed at it '+pg+'/'+z.marks.length+'; that plus the kick out beforehand '+pq+'/'+z.marks.length+'.');
    var fa=z.calls.filter(function(c){ return c.fresh && !c.marked; });
    h.push('Live false calls: '+fa.length+(fa.length?' ('+fa.filter(function(c){ return c.fakeLater; }).length+' later read as fakes) at '+fa.map(function(c){ return fmt(c.d); }).join(', '):'')+'.');
  } else {
    var fr=z.calls.filter(function(c){ return c.fresh; });
    h.push('Live drop calls: '+fr.length+', '+fr.filter(function(c){ return !c.final; }).length+' of them not drops in the full-file view. Mark drops to score it.');
  }
  if(z.gate){ var R=z.gate.react, G=z.gate.gated.filter(function(x){ return x.fire; });
    h.push('<b style="color:var(--ink)">Kick strobe, reactive (today):</b> '+R.length+' flashes \u00b7 '+R.filter(function(x){ return !x.want; }).length+' in breakdowns/builds \u00b7 '+R.filter(function(x){ return x.dbl; }).length+' double-triggers (&lt;150 ms apart).');
    h.push('<b style="color:var(--ink)">Kick strobe, section-gated (live):</b> '+G.length+' flashes \u00b7 '+G.filter(function(x){ return !x.want; }).length+' in breakdowns/builds \u00b7 '+z.gate.gated.filter(function(x){ return x.missed; }).length+' on-beat groove kicks missed (dark until the live view forms, ~30 s into a session, and for the first bar after a drop; off-beat bass hits are skipped on purpose).'); }
  h.push('<span style="color:#7c828c">Lane under the phrase view = what the live tracker believed during each bar; white tick = live drop call, grey = one the full view disagrees with. Strobe rows: top = reactive, bottom = gated; green = flash in a groove, red = flash in a break/build, orange = double-trigger, grey = gated flash missed in a groove.</span>');
  return h.join('<br>');
}
