document.getElementById('clearmk').addEventListener('click',function(){
  if(!TL) return; var nm=TL.ev.filter(function(e){ return e.k==='m'; }).length;
  if(!nm){ msg.textContent='No marks to clear.'; return; }
  if(!confirm('Delete all '+nm+' marks in this file? This can\u2019t be undone.')) return;
  fetch('/logmarksclear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:NAME})})
    .then(function(r){ if(!r.ok) throw new Error(r.status); TL.ev=TL.ev.filter(function(e){ return e.k!=='m'; }); SEL=null; rerender(); msg.textContent='Cleared '+nm+' marks.'; })
    .catch(function(){ msg.textContent='Could not clear the marks.'; });
});
// ---- Live dry-run report (26v): the Pi's own decisions ({k:'x'}) vs hindsight (full-file view) and your marks
function liveReport(){
  var X=TL.ev.filter(function(e){ return e.k==='x'; }); if(!X.length || !TL.sec || !TL.sec.bars.length) return null;
  var S=TL.sec, FB=S.bars, beat=S.barMs/4, of=function(x){ return x==='G'||x==='L'?'groove':x==='U'?'build':'break'; };
  var fin=function(t){ var lo=0, hi=FB.length-1; while(lo<hi){ var m=(lo+hi+1)>>1; if(FB[m].t<=t+beat/2) lo=m; else hi=m-1; } return FB[lo]; };
  var bars=X.filter(function(o){ return o.ev==='bar'; }).map(function(o){ return {bt:o.bt, len:4*beat, look:o.look, pb:o.pb, ms:o.ms, t:o.t}; });
  var agree=0, pbOk=0; bars.forEach(function(b){ var f=fin(b.bt); if(Math.abs(f.t-b.bt)<beat/2){ if(of(f.st)===b.look) agree++; if(f.pb===b.pb) pbOk++; } });
  var marks=TL.ev.filter(function(e){ return e.k==='m' && e.label==='drop'; }).map(function(e){ return e.t; });
  var truth=marks.length?marks:S.drops, tsrc=marks.length?'your marks':'the full-file view';
  var calls=X.filter(function(o){ return o.ev==='drop'; }), hits=X.filter(function(o){ return o.ev==='hit'; }), miss=X.filter(function(o){ return o.ev==='miss'; }), black=X.filter(function(o){ return o.ev==='black'; });
  var near=function(a,b,w){ return Math.abs(a-b)<=w; };
  var perDrop=truth.map(function(d){ var c=calls.filter(function(o){ return near(o.at,d,8*beat); })[0], h=hits.filter(function(o){ return near(o.at,d,beat); })[0];
    return {d:d, lat:c?(c.t-d)/beat:null, onOne:!!h}; });
  var falseCalls=calls.filter(function(o){ return !truth.some(function(d){ return near(o.at,d,8*beat); }); }), falseHits=hits.filter(function(o){ return !truth.some(function(d){ return near(o.at,d,beat); }); });
  var ms=bars.map(function(b){ return b.ms; }).filter(function(v){ return v!=null; }).sort(function(a,b){ return a-b; }), msMax=ms.length?ms[ms.length-1]:0, msMed=ms.length?ms[ms.length>>1]:0;
  var got=perDrop.filter(function(p){ return p.lat!=null || p.onOne; }), onOne=perDrop.filter(function(p){ return p.onOne; }), lats=perDrop.filter(function(p){ return p.lat!=null; }).map(function(p){ return p.lat; }).sort(function(a,b){ return a-b; });
  var ag=bars.length?agree/bars.length:0, lateBlack=black.filter(function(o){ return o.late>beat/4; }).length;   // a 100 ms step always lands a little after the beat; late = more than a quarter beat
  var why=[];
  if(!truth.length) why.push('no drops in this recording');
  else { if(got.length<truth.length) why.push((truth.length-got.length)+' drop'+(truth.length-got.length>1?'s':'')+' never caught');
    if(lats.length && lats[lats.length>>1]>8) why.push('drops caught late (typically '+Math.round(lats[lats.length>>1])+' beats)'); }
  if(falseHits.length) why.push(falseHits.length+' false drop hit'+(falseHits.length>1?'s':'')+' (lights would have fired on nothing)');
  if(bars.length && ag<0.8) why.push('sections agree only '+Math.round(ag*100)+'%');
  if(msMax>250) why.push('engine too slow (max '+msMax+' ms)');
  var v=!truth.length?'INCONCLUSIVE':why.length?'NOT READY':'READY';
  var col=v==='READY'?'#39d353':v==='NOT READY'?'#ff6b6b':'#ffb020';
  var line=v==='READY'?'ready for a lights test':v==='INCONCLUSIVE'?why[0]+' \u2014 record a set with drops':why.join('; ');
  var sim=X.some(function(o){ return o.sim; });
  var h=['<div style="border:1px solid '+col+';border-radius:8px;padding:8px 10px;margin:4px 0 8px"><b style="color:'+col+'">LIVE DRY RUN'+(sim?' (simulated here)':'')+': '+v+'</b> \u2014 '+line+'.'];
  h.push('<br><span style="color:var(--ink)">Drops</span> ('+tsrc+'): caught '+got.length+'/'+truth.length+(onOne.length?' \u00b7 '+onOne.length+' hit on the 1':'')+(lats.length?' \u00b7 called typically '+Math.round(lats[lats.length>>1])+' beats after':'')+' \u00b7 false hits '+falseHits.length+' \u00b7 false calls '+falseCalls.length+'.');
  h.push('<br><span style="color:var(--ink)">Predictions</span>: '+(hits.length+miss.length)+' (hit '+hits.length+', dark beat only '+miss.length+')'+(black.length?' \u00b7 blackouts '+black.length+(lateBlack?' ('+lateBlack+' late)':''):'')+'.');
  h.push('<br><span style="color:var(--ink)">Sections</span>: '+bars.length+' bars decided live \u00b7 look agrees with hindsight '+Math.round(ag*100)+'% \u00b7 phrase count '+(bars.length?Math.round(pbOk/bars.length*100):0)+'%.');
  h.push('<br><span style="color:var(--ink)">Engine</span>: '+msMed+' ms per step typical, max '+msMax+' ms.');
  h.push('<br><span style="color:#7c828c">Live lane (bottom): look per bar as decided on the Pi; white = drop call, green = hit, red = predicted but no kick (one dark beat), grey = cancelled, black = blackout.</span></div>');
  return {x:X, bars:bars, verdict:v, reason:v==='READY'?'':(why[0]||''), html:h.join('')};
}
// 26w: simulate the Pi's live engine on THIS file (uploaded tracks included): feed its frames/hits in 100 ms
// steps, exactly as the bridge page would, and add the decisions (sim:true, in memory only) -> the same verdict.
// A clean digital file is kinder than the room mic, so a real Pi recording is still the final word.
document.getElementById('livebtn').addEventListener('click',function(){
  if(!TL) return; var out=document.getElementById('liveout'), btn=this;
  var E=TL.ev.filter(function(e){ return e.k!=='x' && e.k!=='m' && typeof e.t==='number'; }).sort(function(a,b){ return a.t-b.t; });
  if(E.length<100){ out.textContent='Not enough data in this file.'; return; }
  var L=new LiveEngine(), res=[], i=0, now=0, end=E[E.length-1].t, t0=Date.now(); btn.disabled=true;
  (function chunk(){ var c0=Date.now();
    while(now<=end && Date.now()-c0<40){ while(i<E.length && E[i].t<=now) L.push(E[i++]); L.step(now).forEach(function(o){ o.t=now; o.sim=true; res.push(o); }); now+=100; }
    out.textContent='Simulating the Pi\u2026 '+Math.round(Math.min(1,now/end)*100)+'%';
    if(now<=end){ setTimeout(chunk,0); return; }
    btn.disabled=false; TL.ev=TL.ev.filter(function(e){ return e.k!=='x'; }).concat(res);
    rerender(); out.textContent='Done in '+((Date.now()-t0)/1000).toFixed(1)+' s \u2014 verdict at the top of the stats (not saved to the file).';
    var st=document.getElementById('tlstats'); if(st && st.scrollIntoView) st.scrollIntoView({block:'start'}); })();
});
